import { describe, expect, it } from 'vitest';
import { hasPromptScriptMarker, isPromptScriptOwnedOutput } from './output-ownership.js';

const OPENCODE_PLUGIN =
  '// promptscript-generated: opencode-plugin\nexport const PromptScriptHooks = {};\n';
const LEGACY_OPENCODE_PLUGIN =
  '// Generated by PromptScript - do not edit.\nexport const PromptScriptHooks = {};\n';

describe('output ownership', () => {
  it('recognizes generated OpenCode plugins', () => {
    expect(hasPromptScriptMarker(OPENCODE_PLUGIN)).toBe(true);
    expect(isPromptScriptOwnedOutput('.opencode/plugins/promptscript.ts', OPENCODE_PLUGIN)).toBe(
      true
    );
    expect(
      isPromptScriptOwnedOutput('.opencode/plugins/promptscript.ts', LEGACY_OPENCODE_PLUGIN)
    ).toBe(true);
  });

  it('preserves unmarked OpenCode plugins', () => {
    expect(
      isPromptScriptOwnedOutput(
        '.opencode/plugins/promptscript.ts',
        'export const PromptScriptHooks = {};\n'
      )
    ).toBe(false);
  });
});
